solution.solution.py:
def to_upper(text):
    out = ""
    for ch in text:
        if "a" <= ch <= "z":
            ch = chr(ord(ch) - 32)
        out += ch
    return out

def digit_value(ch):
    return ord(ch) - ord("0")

def parse_number(text):
    value = 0
    for ch in text:
        value = value * 10 + digit_value(ch)
    return value

unitTests:
@test("upper case is 32 lower")
def _():
    check_eq(to_upper("hello"), "HELLO")
    check_eq(to_upper("Hi, there 2!"), "HI, THERE 2!")
    check_eq(to_upper("{z}"), "{Z}")
    check_eq(to_upper(""), "")

@test("digits")
def _():
    check_eq(digit_value("0"), 0)
    check_eq(digit_value("7"), 7)
    check_eq(digit_value("9"), 9)

@test("reading a number from text")
def _():
    check_eq(parse_number("4072"), 4072)
    check_eq(parse_number("0"), 0)
    check_eq(parse_number("007"), 7)
    check_eq(parse_number("2147483647"), 2147483647)

